import pathlib
def _load():
    ns = {}
    for f in pathlib.Path('.').rglob('*.py'):
        try:
            t = f.read_text()
        except Exception:
            continue
        if 'def shortest_path' in t:
            exec(t, ns)
            return ns['shortest_path']
    raise FileNotFoundError('shortest_path not found')

def test_dict_basic():
    sp = _load()
    assert sp({0: [1], 1: [2], 2: []}, 0, 2) == 2
    assert sp({0: [1]}, 0, 0) == 0
    assert sp({0: [1]}, 0, 5) == -1

def test_matrix_basic():
    sp = _load()
