import pathlib, importlib.util
def _load():
    cands = []
    for p in pathlib.Path('.').rglob('*.py'):
        if p.name.startswith('test_'):
            continue
        if 'conftest' in p.name:
            continue
        try:
            t = p.read_text()
        except:
            continue
        if 'def shortest_path' in t:
            cands.append(p)
    assert cands, 'implementation not found'
    p = cands[0]
    spec = importlib.util.spec_from_file_location('impl_mod', str(p))
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod
def test_matrix_line():
    m = _load()
